# Generated by the start-bridge codemod for learn; re-run it instead of editing.
"""Validate and preserve the learn staging artifact; never deploy.

Reuses the reviewed Apps seal/restore implementation with this app's Worker
identity, public files and source-SHA channel.
"""
import importlib.util
import os
from pathlib import Path

WORKER = "tuturuuu-learn-vite-staging"
PRODUCTION_WORKER = "tuturuuu-learn"
PUBLIC_FILES = (
    "robots.txt",
    "sitemap.xml",
)


def load(profile="staging"):
    if profile not in ("staging", "production"):
        raise ValueError("unknown Learn artifact profile")
    path = Path(__file__).with_name("apps-native-artifact.py")
    spec = importlib.util.spec_from_file_location("learn_native_artifact_base", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.IDENTITY = {
        **module.IDENTITY,
        "name": WORKER,
        "compatibility_date": "2026-10-12",
        "compatibility_flags": ["nodejs_compat","global_fetch_strictly_public"],
        "workers_dev": True,
    }
    module.NORMALIZED_DEFAULTS = {**module.NORMALIZED_DEFAULTS, "topLevelName": WORKER}
    module.RECEIPT = "learn-native-artifact.json"
    module.PUBLIC_FILES = PUBLIC_FILES
    if profile == "production":
        module.IDENTITY = {
            **module.IDENTITY,
            "name": PRODUCTION_WORKER,
            "workers_dev": False,
            "vars": {
                "TUTURUUU_NOINDEX": "0",
                "NODE_ENV": "production",
                "TUTURUUU_REQUIRE_SECRETS": "1",
                "NEXT_PUBLIC_APP_URL": "https://learn.tuturuuu.com",
                "NEXT_PUBLIC_WEB_APP_URL": "https://tuturuuu.com",
            },
        }
        module.NORMALIZED_DEFAULTS = {
            **module.NORMALIZED_DEFAULTS,
            "topLevelName": PRODUCTION_WORKER,
            "preview_urls": False,
            "upload_source_maps": False,
        }
        module.RECEIPT = "learn-production-artifact.json"
    return module


def main():
    import sys
    profile = "staging"
    if len(sys.argv) > 1 and sys.argv[1] == "--profile":
        profile = sys.argv[2]
        del sys.argv[1:3]
    # The shared CLI reads its exact source from APPS_SOURCE_SHA.
    if "LEARN_SOURCE_SHA" in os.environ:
        os.environ["APPS_SOURCE_SHA"] = os.environ["LEARN_SOURCE_SHA"]
    else:
        os.environ.pop("APPS_SOURCE_SHA", None)
    load(profile).main()


if __name__ == "__main__":
    main()
